'use client';

import React from 'react';

/** Status of the reasoning step. */
export type ReasoningStepStatus = 'pending' | 'active' | 'completed' | 'error';

/** Props for the {@link ReasoningStep} component. */
export interface ReasoningStepProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Current status of this step. */
  status: ReasoningStepStatus;
  /** Title text displayed in the header. */
  title: string;
  /** Whether the step is expanded by default. */
  defaultExpanded?: boolean;
  /** Additional CSS class names. */
  className?: string;
  /** Step content, shown when expanded. */
  children?: React.ReactNode;
}

/**
 * Expandable reasoning trace step.
 * Renders a collapsible section with a status indicator icon.
 */
export const ReasoningStep = React.forwardRef<HTMLDivElement, ReasoningStepProps>(
  ({ status, title, defaultExpanded, className, children, ...rest }, ref) => {
    const [expanded, setExpanded] = React.useState(defaultExpanded ?? false);
    const icon =
      status === 'completed' ? '\u2713' :
      status === 'error'     ? '\u2717' :
      status === 'active'    ? '\u25B8' : '\u25CB';

    return (
      <div
        ref={ref}
        className={`sk-reasoning-step${className ? ` ${className}` : ''}`}
        data-status={status}
        data-expanded={expanded ? 'true' : 'false'}
        {...rest}
      >
        <button
          className="sk-reasoning-step__header"
          aria-expanded={expanded}
          onClick={() => setExpanded((e) => !e)}
        >
          <span className="sk-reasoning-step__indicator">{icon}</span>
          <span className="sk-reasoning-step__title">{title}</span>
          <span className="sk-reasoning-step__chevron">{expanded ? '\u25BE' : '\u25B8'}</span>
        </button>
        {expanded && children && (
          <div className="sk-reasoning-step__content">{children}</div>
        )}
      </div>
    );
  },
);

ReasoningStep.displayName = 'ReasoningStep';

/**
 * skeehn — ReasoningStep Component
 *
 * @component sk-reasoning-step
 * @statuses  pending | active | completed | error
 * @slots     __header __indicator __title __chevron __content __step-number __duration
 * @a11y      aria-expanded, keyboard nav, status color + text, focus ring
 * @design    Mono chrome header, SANS reasoning prose, readable metadata, timeline rail.
 */

.sk-reasoning-step { margin-bottom: var(--sk-space-3); border: var(--sk-border); border-radius: var(--sk-radius-sm); overflow: hidden; font-family: var(--sk-font-mono); }
.sk-reasoning-step__header { display: flex; align-items: center; gap: var(--sk-space-2); padding: var(--sk-space-2) var(--sk-space-3); background: hsl(var(--sk-muted)); cursor: pointer; transition: background var(--sk-transition-fast); }
.sk-reasoning-step__header:hover { background: hsl(var(--sk-secondary)); }
.sk-reasoning-step__header:focus-visible { outline: var(--sk-focus-ring); outline-offset: -2px; }
.sk-reasoning-step__indicator { width: 8px; height: 8px; border-radius: 50%; flex-shrink: 0; background: hsl(var(--sk-muted-foreground)); }
.sk-reasoning-step[data-status="active"] .sk-reasoning-step__indicator { background: hsl(var(--sk-info)); box-shadow: 0 0 8px hsl(var(--sk-info) / 0.6); animation: sk-dither-pulse 1.5s ease-in-out infinite; }
.sk-reasoning-step[data-status="completed"] .sk-reasoning-step__indicator { background: hsl(var(--sk-success)); }
.sk-reasoning-step[data-status="error"] .sk-reasoning-step__indicator { background: hsl(var(--sk-destructive)); }
.sk-reasoning-step__title { flex: 1; font-size: var(--sk-font-size-sm); font-weight: 600; color: hsl(var(--sk-foreground)); }
.sk-reasoning-step__chevron { font-size: var(--sk-font-size-xs); color: hsl(var(--sk-muted-foreground)); transition: transform var(--sk-transition); }
.sk-reasoning-step[data-expanded="true"] .sk-reasoning-step__chevron { transform: rotate(90deg); }

/* Content — SANS reasoning prose, readable */
.sk-reasoning-step__content {
  padding: var(--sk-space-3) var(--sk-space-4);
  font-family: var(--sk-font-sans);
  font-size: var(--sk-font-size-sm);
  color: hsl(var(--sk-muted-foreground));
  line-height: var(--sk-line-height-relaxed);
  position: relative;
  background: hsl(var(--sk-surface));
  border-top: var(--sk-border);
}
.sk-reasoning-step[data-expanded="true"] .sk-reasoning-step__content::before { content: ""; position: absolute; inset: 0; background-image: var(--sk-dither-pattern); background-repeat: repeat; opacity: var(--sk-dither-opacity-subtle); pointer-events: none; }
.sk-reasoning-step__content > * { position: relative; z-index: 1; }
.sk-reasoning-step[hidden] .sk-reasoning-step__content { display: none; }

/* Timeline connector */
.sk-reasoning-steps { position: relative; padding-left: var(--sk-space-6); }
.sk-reasoning-steps::before { content: ""; position: absolute; left: calc(var(--sk-space-3) - 1px); top: var(--sk-space-4); bottom: var(--sk-space-4); width: 2px; background: hsl(var(--sk-border-color)); }
.sk-reasoning-steps .sk-reasoning-step { position: relative; }

/* Step numbers — readable */
.sk-reasoning-step__step-number {
  display: inline-flex; align-items: center; justify-content: center;
  width: 1.5rem; height: 1.5rem;
  font-family: var(--sk-font-mono); font-size: var(--sk-font-size-xs); font-weight: 700;
  border-radius: 50%; background: hsl(var(--sk-muted)); color: hsl(var(--sk-muted-foreground));
  flex-shrink: 0;
}
.sk-reasoning-step[data-status="completed"] .sk-reasoning-step__step-number { background: hsl(var(--sk-success) / 0.15); color: hsl(var(--sk-success)); }
.sk-reasoning-step[data-status="active"]    .sk-reasoning-step__step-number { background: hsl(var(--sk-info) / 0.15); color: hsl(var(--sk-info)); }
.sk-reasoning-step[data-status="error"]     .sk-reasoning-step__step-number { background: hsl(var(--sk-destructive) / 0.15); color: hsl(var(--sk-destructive)); }

/* Duration badge — readable */
.sk-reasoning-step__duration {
  font-family: var(--sk-font-mono); font-size: var(--sk-font-size-xs);
  color: hsl(var(--sk-muted-foreground) / 0.75); letter-spacing: var(--sk-letter-spacing-wide);
  margin-left: auto; padding-left: var(--sk-space-2); font-variant-numeric: tabular-nums;
}

/* Loading & skeleton */
.sk-reasoning-step[data-loading] .sk-reasoning-step__content { position: relative; opacity: 0.5; }
.sk-reasoning-step[data-loading] .sk-reasoning-step__content::after { content: ""; position: absolute; inset: 0; background-image: var(--sk-dither-pattern); background-repeat: repeat; opacity: var(--sk-dither-opacity-normal); animation: sk-pulse-dither 1.5s ease-in-out infinite; pointer-events: none; }
.sk-reasoning-step[data-skeleton] .sk-reasoning-step__title { color: transparent; background: linear-gradient(90deg, hsl(var(--sk-muted)) 25%, hsl(var(--sk-secondary)) 50%, hsl(var(--sk-muted)) 75%); background-size: 200% 100%; animation: sk-shimmer 1.8s ease-in-out infinite; border-radius: var(--sk-radius-sm); }

@media print {
  .sk-reasoning-step { border: 1px solid hsl(var(--sk-foreground)); break-inside: avoid; }
  .sk-reasoning-step__content { display: block; }
  .sk-reasoning-step__chevron { display: none; }
  .sk-reasoning-step[data-skeleton] { display: none; }
  .sk-reasoning-steps::before { background: hsl(var(--sk-foreground)); }
}
@media (prefers-reduced-motion: reduce) {
  .sk-reasoning-step__header, .sk-reasoning-step__chevron { transition: none; }
  .sk-reasoning-step[data-status="active"] .sk-reasoning-step__indicator { animation: none; }
  .sk-reasoning-step[data-loading] .sk-reasoning-step__content::after { animation: none; }
  .sk-reasoning-step[data-skeleton] .sk-reasoning-step__title { animation: none; background: hsl(var(--sk-muted)); }
}
